// One made-up review so the review frame works straight after import. It is labelled as a sample on the frame,
// and the Review lane refuses to book a pin that uses it. Add your own reviews to pin_reviews (source "own").
return [{ json: {
  product_handle: $('Setup settings').first().json.sample_review_handle,
  rating: 5,
  quote: 'Easy to set up and exactly as described. It still looks new after a month, and I would buy it again.',
  author: 'Sample Customer',
  source: 'sample',
  verified: false
} }];

// The query only returns products published to the Online Store; store_url builds the link if Shopify hasn't given one yet.
// Which products get a pin now, and which pin. One pin per product at a time: a product with a draft, scheduled or failed pin waits.
// Each product works through pin_sequence (photo, headline, review, photo_2), one step every next_pin_after_days, skipping a step it can't make
// (no qualifying review, no second photo). First pins always go before anyone's later pins. Only the free slots in max_waiting are filled.
const s = $('Draft settings').first().json;
const pins = $('Get all pins').all().map(i => i.json).filter(r => r.product_id);
const reviews = $('Get reviews').all().map(i => i.json).filter(r => r.quote);
const pages = $('Get products').all().map(i => i.json);
const bad = pages.find(p => p.errors);
if (bad) throw new Error('Shopify: ' + JSON.stringify(bad.errors).slice(0, 300));
const products = pages.flatMap(p => p.data?.products?.nodes || []);
const free = Math.max(0, s.max_waiting - pins.filter(r => r.status === 'draft').length);
if (!free) return [];

const text = h => String(h || '').replace(/<li[^>]*>/gi, '; ').replace(/<[^>]+>/g, ' ').replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&').replace(/\s+/g, ' ').replace(/^[;\s]+/, '').trim();
const words = t => String(t || '').toLowerCase();
const has = (title, w) => new RegExp('(^|[^a-z0-9])' + w.toLowerCase().replace(/[.*+?^${}()|[\]\\]/g, '\\$&') + '($|[^a-z0-9])').test(words(title));
const boardFor = p => s.boards.find(b => (b.match.title_words || []).some(w => has(p.title, w))
  || (b.match.product_types || []).includes(p.productType)
  || (b.match.categories || []).some(c => p.category && (p.category.name === c || String(p.category.fullName).includes(c))));
const skip = s.skip_words ? new RegExp(s.skip_words, 'i') : null;
const day = 864e5, now = Date.now();
const big = im => im && Math.min(im.width || 0, im.height || 0) >= s.min_photo_px;
const base = u => String(u || '').split('?')[0];

const out = [];
for (const p of products) {
  const board = boardFor(p);
  if (!board || (skip && skip.test(p.title))) continue;
  const main = p.featuredMedia?.image;
  const url = p.onlineStoreUrl || (s.store_url.replace(/\/$/, '') + '/products/' + p.handle);
  if (!big(main) || !(Number(p.priceRangeV2?.minVariantPrice?.amount) > 0) || text(p.descriptionHtml).length < 30) continue;
  const id = String(p.legacyResourceId);
  const mine = pins.filter(r => String(r.product_id) === id);
  if (mine.some(r => ['draft', 'scheduled', 'failed'].includes(r.status))) continue;
  if (mine.some(r => Number(r.pin_no) === 1 && r.status === 'skipped')) continue;   // skipping a first pin stops the product
  const last = Math.max(0, ...mine.map(r => new Date(r.posted_at || r.decided_at || r.createdAt || 0).getTime()));
  if (mine.length && now - last < s.next_pin_after_days * day) continue;
  const done = mine.map(r => r.pin_kind);
  const others = (p.media?.nodes || []).map(m => m.image).filter(im => big(im) && base(im.url) !== base(main.url) && !mine.some(r => base(r.source_image) === base(im.url)));
  const review = reviews.filter(r => r.product_handle === p.handle && Number(r.rating) >= s.review_min_rating && String(r.quote).length <= s.review_max_chars
    && s.review_sources.includes(r.source) && !mine.some(m => m.review_quote === r.quote))
    .sort((a, b) => (b.verified === true) - (a.verified === true) || b.rating - a.rating)[0];
  let kind = null, photo = main;
  for (const k of s.pin_sequence) {
    if (done.includes(k)) continue;
    if (k === 'review' && !review) continue;
    if (k === 'photo_2') { if (!others.length) continue; photo = others[0]; }
    kind = k; break;
  }
  if (!kind) continue;
  const pinNo = mine.length + 1;
  const desc = String(p.descriptionHtml || '');
  const cut = desc.search(/<h[2-4]/i);
  const intro = text(cut >= 0 ? desc.slice(0, cut) : desc).slice(0, 800);
  const specs = text(cut >= 0 ? desc.slice(cut) : '').slice(0, 3000);
  // search phrases that fit this product: every distinctive word in the phrase is in the title or intro
  const hay = words(p.title + ' ' + intro).replace(/wi-fi/g, 'wifi');
  const fits = x => x.toLowerCase().split(' ').filter(w => !['security', 'camera', 'cameras', 'for', 'the', 'a'].includes(w)).every(w => hay.includes(w.replace(/s$/, '')));
  const good = [...new Set((board.phrases || []).filter(fits).map(x => x.replace(/\bcameras\b/gi, 'camera')))];
  const lead = good.length ? good[(pinNo - 1) % good.length] : (board.phrases || [board.name])[0];
  const earlier = mine.filter(r => r.title).map(r => r.title + ' / ' + r.description);
  const src = base(photo.url);
  out.push({ json: {
    product_id: id, product_title: p.title, handle: p.handle, brand: p.vendor || '', category: p.category?.name || p.productType || '',
    created: p.createdAt, pin_no: pinNo, pin_kind: kind, board_key: board.key, board_name: board.name, board_id: board.board_id,
    search_phrase: lead, other_phrases: good.filter(x => x !== lead).join(', '), intro, specs,
    source_image: photo.url, photo_url: src + '?width=1024',
    image_url: ['photo', 'photo_2'].includes(kind) ? s.image_template.replace('{url}', encodeURIComponent(src)) : '',
    link: url + (url.includes('?') ? '&' : '?') + s.utm,
    review_quote: kind === 'review' ? review.quote : '', review_rating: kind === 'review' ? Number(review.rating) : null,
    review_author: kind === 'review' ? review.author : '', review_source: kind === 'review' ? review.source : '',
    earlier: earlier.join('\n')
  } });
}
out.sort((a, b) => a.json.pin_no - b.json.pin_no || String(a.json.created).localeCompare(String(b.json.created)));
return out.slice(0, free);

// The vision model's answer per photo, plus the input for the writer. A second photo that turns out to be a box,
// a diagram or unreadable is dropped (the product moves on to its next pin next time).
const s = $('Draft settings').first().json;
const picked = $('Pick the next pins').all().map(i => i.json);
const out = [];
$input.all().forEach((it, i) => {
  const p = picked[i]; if (!p) return;
  const r = it.json || {};
  let txt = r.content ?? r.text ?? r.response ?? r.message?.content ?? r.output ?? '';
  if (typeof txt !== 'string') txt = JSON.stringify(txt);
  let v = {};
  try { v = JSON.parse(txt.slice(txt.indexOf('{'), txt.lastIndexOf('}') + 1)); } catch (e) {}
  const kind = ['product', 'in_use', 'packaging', 'diagram', 'other'].includes(v.kind) ? v.kind : '';
  const alt = String(v.alt || '').replace(/\s+/g, ' ').trim().slice(0, 300);
  if (p.pin_kind === 'photo_2' && !['product', 'in_use'].includes(kind)) return;
  const lines = [
    'Product: ' + p.product_title, 'Brand: ' + (p.brand || 'unknown'), 'Category: ' + (p.category || 'unknown'),
    'Search phrase: ' + p.search_phrase, 'Other searches: ' + (p.other_phrases || 'none'),
    'Intro: ' + (p.intro || 'none'), 'Specs: ' + (p.specs || 'none'), 'The photo shows: ' + (alt || 'the product on a white background')
  ];
  if (p.pin_kind === 'review') lines.push('This pin shows this customer review on the image (do not quote it or mention reviews): ' + p.review_quote);
  if (p.earlier) lines.push('Earlier pins for this product. Your title and first sentence must differ from every one of them (keep the search phrase first, change what follows it):\n' + p.earlier);
  out.push({ json: { ...p, photo_kind: kind || null, photo_alt: alt, prompt_input: lines.join('\n') } });
});
return out;

// Parse the model's lines and hold them to the pin rules. Safe fixes are made (dashes, hashtags, casing, the closing line);
// everything else becomes a warning on the card, so the reviewer sees it before approving. A model failure saves nothing.
const s = $('Draft settings').first().json;
const items = $('Read the photo').all().map(i => i.json);
const CLOSE = s.closing_line;
const out = [];
$input.all().forEach((it, i) => {
  const p = items[i]; if (!p) return;
  const raw = String(it.json.text || it.json.output || '');
  if (it.json.error || !raw.trim()) return;   // tried again next run
  const grab = label => { const m = raw.match(new RegExp('^\\s*\\**' + label + '\\**\\s*:\\s*(.+)$', 'im')); return m ? m[1].trim().replace(/^["“]|["”]$/g, '') : ''; };
  const fix = x => x.replace(/—|–/g, ', ').replace(/\s+,/g, ',').replace(/#\w+/g, '').replace(/\s{2,}/g, ' ').trim();
  const caps = x => s.keep_terms.reduce((t, k) => t.replace(new RegExp('\\b' + k.replace(/-/g, '-?') + '\\b', 'gi'), k), x);
  const local = x => /australian|british|new zealand|canadian/i.test(s.language)
    ? x.replace(/\bcolor(s|ed|ful)?\b/gi, (m, e) => (m[0] === 'C' ? 'Colour' : 'colour') + (e || '')).replace(/\bcenter(s|d)?\b/gi, (m, e) => (m[0] === 'C' ? 'Centre' : 'centre') + (e || '')).replace(/\b(meter|meters)\b/gi, m => m.replace(/er/i, 're'))
    : x;
  const clean = x => local(caps(fix(x)));
  let title = clean(grab('Pin title')), description = clean(grab('Description'));
  const headline = clean(grab('Headline')), productLine = clean(grab('Product line'));
  const alt = clean(p.photo_alt || grab('Alt text'));
  if (description && !description.endsWith(CLOSE)) description = description.replace(/[.\s]+$/, '') + '. ' + CLOSE;
  const problems = [];
  if (title.length > 100) problems.push(`Title is ${title.length} characters (100 max).`);
  if (title.length < 25) problems.push('Title is under 25 characters.');
  if (description.length > 600) problems.push(`Description is ${description.length} characters (aim for 300 to 500).`);
  if (description.length < 240) problems.push(`Description is short (${description.length} characters, aim for 300 to 500).`);
  if (p.pin_kind === 'headline') {
    if (!headline) problems.push('No headline for the frame.');
    if (headline.length > 40) problems.push(`Headline is ${headline.length} characters (40 fits the frame).`);
    if (/\$|%|\d+\s*off\b/i.test(headline + ' ' + productLine)) problems.push('Price or discount on the image.');
  }
  const all = [title, description, alt, headline, productLine].join(' ');
  if (/https?:\/\/|www\./i.test(all)) problems.push('Has a web link.');
  if (/\$\s?\d/.test(all)) problems.push('Mentions a price.');
  if (/\p{Extended_Pictographic}/u.test(all)) problems.push('Has an emoji.');
  const banned = s.banned_words ? all.replace(new RegExp(s.store_name, 'g'), '').match(new RegExp(s.banned_words, 'i')) : null;
  if (banned) problems.push(`Uses "${banned[0]}".`);
  const key = p.search_phrase.toLowerCase().split(' ').filter(w => w.length > 2);
  if (key.length && !key.some(w => title.toLowerCase().includes(w.replace(/s$/, '')))) problems.push(`Title doesn't use the search phrase "${p.search_phrase}".`);
  if (p.photo_kind === 'packaging') problems.push('The photo shows the box, not the product. Consider Skip.');
  if (p.earlier && p.earlier.toLowerCase().includes(title.toLowerCase())) problems.push('Same title as an earlier pin.');
  if (/\b(this|the) (image|photo|picture)\b/i.test(description)) problems.push('Talks about the photo instead of the product.');
  out.push({ json: { ...p, title, description, alt_text: alt, headline: p.pin_kind === 'headline' ? headline : '', product_line: p.pin_kind === 'headline' ? productLine : '',
    problems: JSON.stringify(problems) } });
});
return out;

// One Slack card for one pin, in whatever state it is in. Every lane redraws the card through here, so it always matches the row.
const s = $('Card settings').first().json;
const r = $input.first().json;
const esc = x => String(x ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const when = t => t ? DateTime.fromISO(new Date(t).toISOString()).setZone(s.timezone).toFormat('ccc d LLL, h:mm a').replace('AM', 'am').replace('PM', 'pm') : '';
const kinds = { photo: 'photo', headline: 'headline frame', review: 'review frame', photo_2: 'second photo' };
const head = { draft: 'Pin draft', scheduled: 'Scheduled', skipped: 'Skipped', posted: 'Pinned', failed: 'Pin failed' }[r.status] || 'Pin';
const v = String(r.id);
const blocks = [{ type: 'header', text: { type: 'plain_text', text: (head + ': ' + r.product_title).slice(0, 150) } },
  { type: 'context', elements: [{ type: 'mrkdwn', text: `Pin ${r.pin_no} · ${kinds[r.pin_kind] || r.pin_kind}` }] }];
if (r.status === 'skipped') {
  blocks.push({ type: 'context', elements: [{ type: 'mrkdwn', text: 'Skipped by ' + esc(r.decided_by || 'someone') + (Number(r.pin_no) === 1 ? '. This product gets no pins.' : '. The next pin in the sequence comes later.') }, { type: 'mrkdwn', text: s.workflow_name }] });
  return [{ json: { channel: r.slack_channel, ts: r.slack_ts || '', id: r.id, text: 'Skipped: ' + r.product_title, blocks } }];
}
if (r.image_url) blocks.push({ type: 'image', image_url: r.image_url, alt_text: String(r.alt_text || r.product_title).slice(0, 1900) });
else blocks.push({ type: 'section', text: { type: 'mrkdwn', text: ':hourglass: The frame image is not ready yet.' + (r.error ? ' ' + esc(r.error) : '') } });
blocks.push({ type: 'section', text: { type: 'mrkdwn', text: ('*Pin title* (' + String(r.title || '').length + ')\n' + esc(r.title)).slice(0, 2900) } });
blocks.push({ type: 'section', text: { type: 'mrkdwn', text: ('*Description* (' + String(r.description || '').length + ')\n' + esc(r.description)).slice(0, 2900) } });
blocks.push({ type: 'section', text: { type: 'mrkdwn', text: ('*Alt text*\n' + esc(r.alt_text)).slice(0, 2900) } });
if (r.pin_kind === 'headline') blocks.push({ type: 'section', fields: [{ type: 'mrkdwn', text: '*Headline*\n' + esc(r.headline) }, { type: 'mrkdwn', text: '*Product line*\n' + esc(r.product_line) }] });
if (r.pin_kind === 'review') blocks.push({ type: 'section', text: { type: 'mrkdwn', text: '*Review on the image* ' + '★'.repeat(Number(r.review_rating) || 0) + '\n>' + esc(r.review_quote) + '\n' + esc(r.review_author) + (r.review_source === 'sample' ? ' · :warning: *sample review*, swap in a real one before you approve' : r.review_source !== 'own' ? ' · from ' + esc(r.review_source) : '') } });
blocks.push({ type: 'section', fields: [{ type: 'mrkdwn', text: '*Board*\n' + esc(r.board_name) }, { type: 'mrkdwn', text: '*Link*\n<' + r.link + '|' + esc(String(r.link).split('?')[0].replace('https://', '')) + '>' }] });
let problems = []; try { problems = JSON.parse(r.problems || '[]'); } catch (e) {}
if (problems.length && r.status === 'draft') blocks.push({ type: 'section', text: { type: 'mrkdwn', text: ':warning: ' + problems.map(esc).join('\n:warning: ') } });
if (r.status === 'failed' && r.error) blocks.push({ type: 'section', text: { type: 'mrkdwn', text: ':x: ' + esc(r.error).slice(0, 500) } });
const btn = (text, id, style) => Object.assign({ type: 'button', text: { type: 'plain_text', text }, action_id: id, value: v }, style ? { style } : {});
if (r.status === 'draft') blocks.push({ type: 'actions', elements: [btn('Approve', 'pin_approve', 'primary'), btn('Edit', 'pin_edit'), btn('Skip', 'pin_skip', 'danger')] });
if (r.status === 'scheduled') blocks.push({ type: 'actions', elements: [btn('Cancel', 'pin_cancel', 'danger')] });
if (r.status === 'failed') blocks.push({ type: 'actions', elements: [btn('Try again', 'pin_approve', 'primary'), btn('Edit', 'pin_edit'), btn('Skip', 'pin_skip', 'danger')] });
if (r.status === 'posted' && r.pin_url) blocks.push({ type: 'actions', elements: [{ type: 'button', text: { type: 'plain_text', text: 'Open pin' }, url: r.pin_url, action_id: 'pin_open' }] });
const note = {
  draft: 'Approve books the next free slot. Edit changes the words. Skip drops this pin' + (Number(r.pin_no) === 1 ? ' and the product.' : '.'),
  scheduled: ':calendar: Approved by ' + esc(r.decided_by || 'someone') + '. Posts to *' + esc(r.board_name) + '* on ' + when(r.scheduled_for) + '. Cancel takes it back to a draft.',
  posted: ':pushpin: On Pinterest since ' + when(r.posted_at) + '.',
  failed: 'Not posted. Try again books a new slot.'
}[r.status] || '';
blocks.push({ type: 'context', elements: [{ type: 'mrkdwn', text: note }, { type: 'mrkdwn', text: s.workflow_name }] });
return [{ json: { channel: r.slack_channel, ts: r.slack_ts || '', id: r.id, text: head + ': ' + r.product_title, blocks } }];

// The frame as a 1000 x 1500 web page: the real product photo in a panel, then the headline and product line,
// or the review with its stars and who wrote it. Drawn from the saved row only.
const f = $('Frame settings').first().json;
const r = $input.first().json;
const esc = x => String(x ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
if (!r.id) return [{ json: { html: '<!doctype html><title>Not found</title><p>No pin with that id.</p>', status: 404 } }];
const photo = String(r.source_image || '').split('?')[0] + '?width=1400';
let words;
if (r.pin_kind === 'review') {
  const label = r.review_source === 'sample' ? '<span class="tag">Sample review</span>' : (r.review_source && r.review_source !== 'own' ? '<span class="tag">Review from ' + esc(r.review_source) + '</span>' : '');
  words = `<div class="stars">${'★'.repeat(Number(r.review_rating) || 5)}</div><p class="quote">“${esc(r.review_quote)}”</p><p class="who">${esc(r.review_author)}${label}</p>`;
} else {
  const size = String(r.headline || '').length > 28 ? 72 : 88;
  words = `<h1 style="font-size:${size}px">${esc(r.headline)}</h1><p class="line">${esc(r.product_line)}</p>`;
}
const brand = f.logo_url ? `<img src="${esc(f.logo_url)}" alt="${esc(f.store_name)}">` : `<span>${esc(f.store_name)}</span>`;
const html = `<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=1000">
<link href="https://fonts.googleapis.com/css2?family=${encodeURIComponent(f.font)}:wght@400;600;800&display=swap" rel="stylesheet">
<style>*{box-sizing:border-box;margin:0}html,body{width:1000px;height:1500px;background:#fff}
body{font-family:'${f.font}',sans-serif;color:${f.text_colour};display:flex;flex-direction:column;padding:56px}
.photo{flex:0 0 860px;background:${f.panel_colour};border-radius:32px;display:flex;align-items:center;justify-content:center;overflow:hidden}
.photo img{max-width:90%;max-height:90%;object-fit:contain;mix-blend-mode:multiply}
.words{flex:1;display:flex;flex-direction:column;justify-content:center;padding:36px 12px 12px}
h1{line-height:1.02;font-weight:800;letter-spacing:-0.02em}.line{margin-top:22px;font-size:32px;color:${f.muted_colour}}
.stars{color:${f.accent_colour};font-size:54px;letter-spacing:6px}.quote{margin-top:16px;font-size:48px;line-height:1.2;font-weight:600}
.who{margin-top:22px;font-size:28px;color:${f.muted_colour};display:flex;align-items:center;gap:14px}
.tag{padding:4px 16px;border-radius:999px;background:${f.panel_colour};font-size:22px}
.foot{display:flex;justify-content:space-between;align-items:center;font-size:30px;font-weight:600}.foot img{height:56px}.foot .url{color:${f.muted_colour};font-weight:400}
</style></head><body><div class="photo"><img src="${esc(photo)}" alt="${esc(r.alt_text)}"></div>
<div class="words">${words}</div><div class="foot">${brand}<span class="url">${esc(f.store_url_text)}</span></div></body></html>`;
return [{ json: { html, status: 200 } }];

// The screenshot as a JPEG named after the pin, by way of wsrv.nl. A failed screenshot is passed on with its error.
const s = $('Render settings').first().json;
const r = $('Get the pin to draw').first().json;
const shot = $input.first().json?.data?.screenshot || '';
const name = ('pin-' + String(r.product_title || 'pin').toLowerCase().replace(/[^a-z0-9]+/g, '-').slice(0, 60) + '-' + r.id + '-' + Date.now()).replace(/-+/g, '-');
return [{ json: { id: r.id, old_file_id: r.shopify_file_id || '', alt: r.alt_text || '',
  source: shot ? s.jpeg_template.replace('{name}', name).replace('{url}', encodeURIComponent(shot)) : '',
  error: shot ? '' : 'Firecrawl: ' + String($input.first().json?.error?.message || $input.first().json?.error || 'no screenshot').slice(0, 200) } }];

// The frame's lasting URL, or why there isn't one.
const n = $('Name the file').first().json;
const made = $('Keep it in Shopify').first().json;
const f = $input.first().json?.data?.node || {};
const id = made?.data?.fileCreate?.files?.[0]?.id || '';
const url = f.fileStatus === 'READY' ? (f.image?.url || '') : '';
const error = n.error || (!id ? 'Shopify: ' + JSON.stringify(made?.data?.fileCreate?.userErrors || made?.errors || 'no file').slice(0, 200) : (!url ? 'Shopify is still processing the image (' + (f.fileStatus || 'unknown') + '). Edit and save to draw it again.' : ''));
return [{ json: { id: n.id, file_id: id || n.old_file_id, image_url: url, error, old_file_id: url && n.old_file_id && n.old_file_id !== id ? n.old_file_id : '' } }];

// Slack sends the click as a form field called payload. Keep the raw body for the signature check.
const raw = (await this.helpers.getBinaryDataBuffer(0, 'data')).toString('utf8');
const h = $input.first().json.headers;
if (Math.abs(Date.now() / 1000 - Number(h['x-slack-request-timestamp'])) > 300) throw new Error('Stale request');
const field = raw.split('&').find(kv => kv.startsWith('payload=')) || '';   // no URLSearchParams in the Code node
const b = JSON.parse(decodeURIComponent(field.slice(8).replace(/\+/g, ' ')));
const sig = { base: `v0:${h['x-slack-request-timestamp']}:${raw}`, expected: h['x-slack-signature'] };
const user = b.user?.username || b.user?.name || b.user?.id || 'someone';
if (b.type === 'view_submission') {
  const m = JSON.parse(b.view.private_metadata || '{}');
  const v = b.view.state.values;
  const val = k => v[k]?.[k]?.value ?? null;
  return [{ json: { ...sig, action: 'edit_submit', pin_id: String(m.pin_id), user,
    edit: { title: val('title'), description: val('description'), alt_text: val('alt_text'), headline: val('headline'), product_line: val('product_line') } } }];
}
const a = (b.actions || [])[0] || {};
return [{ json: { ...sig, action: String(a.action_id || '').replace('pin_', ''), pin_id: String(a.value || ''), user,
  trigger_id: b.trigger_id, response_url: b.response_url || '' } }];

// The words of a draft in a modal. A headline pin also gets its headline and product line (saving redraws the frame).
const r = $('Get the clicked pin').first().json;
const c = $('Read the click').first().json;
const input = (key, label, initial, max, multiline) => ({ type: 'input', block_id: key, optional: key === 'alt_text', label: { type: 'plain_text', text: label },
  element: Object.assign({ type: 'plain_text_input', action_id: key, max_length: max, multiline: !!multiline }, initial ? { initial_value: String(initial).slice(0, max) } : {}) });
const editable = ['draft', 'failed'].includes(r.status);
const blocks = [{ type: 'section', text: { type: 'mrkdwn', text: '*' + String(r.product_title || 'Pin').replace(/[<>&]/g, '') + '*' } }];
if (editable) {
  blocks.push(input('title', 'Pin title (search phrase first, 100 max)', r.title, 100), input('description', 'Description', r.description, 800, true), input('alt_text', 'Alt text (what the photo shows)', r.alt_text, 500));
  if (r.pin_kind === 'headline') blocks.push(input('headline', 'Headline on the image (40 fits)', r.headline, 60), input('product_line', 'Product line on the image', r.product_line, 80));
  if (r.pin_kind === 'review') blocks.push({ type: 'context', elements: [{ type: 'mrkdwn', text: 'The review on the image is quoted word for word and can\'t be edited. Skip this pin to drop it.' }] });
} else blocks.push({ type: 'context', elements: [{ type: 'mrkdwn', text: 'This pin is ' + r.status + '. Cancel it on the card first, then edit the draft.' }] });
const view = { type: 'modal', callback_id: 'pin_edit', private_metadata: JSON.stringify({ pin_id: r.id }), title: { type: 'plain_text', text: 'Edit pin' }, close: { type: 'plain_text', text: 'Close' }, blocks };
if (editable) view.submit = { type: 'plain_text', text: 'Save' };
return [{ json: { trigger_id: c.trigger_id, view } }];

// The edited words, held to the same rules as a new draft. Problems show on the card; nothing is blocked.
const r = $('Get the clicked pin').first().json;
const e = $('Read the click').first().json.edit || {};
const pick = (k, d) => (e[k] == null ? d : String(e[k]).replace(/\s+/g, ' ').trim());
const out = { title: pick('title', r.title), description: pick('description', r.description), alt_text: pick('alt_text', r.alt_text),
  headline: pick('headline', r.headline), product_line: pick('product_line', r.product_line) };
const problems = [];
if (out.title.length > 100) problems.push(`Title is ${out.title.length} characters (100 max).`);
if (out.description.length > 800) problems.push(`Description is ${out.description.length} characters (800 max).`);
if (r.pin_kind === 'headline' && out.headline.length > 40) problems.push(`Headline is ${out.headline.length} characters (40 fits the frame).`);
const all = Object.values(out).join(' ');
if (/https?:\/\/|www\./i.test(all)) problems.push('Has a web link.');
if (/#\w/.test(all)) problems.push('Has a hashtag.');
if (/\$\s?\d/.test(all)) problems.push('Mentions a price.');
const redraw = r.pin_kind === 'headline' && (out.headline !== r.headline || out.product_line !== r.product_line);
return [{ json: { ...out, problems: JSON.stringify(problems), redraw, editable: ['draft', 'failed'].includes(r.status) } }];

// The next posting slot: one gap after the latest scheduled or posted pin. The gap is a week divided by the pins a week for
// the account's age at that point (never more than max_per_week), jittered by up to 15%, never sooner than 15 minutes from now,
// and moved into posting hours in your time zone.
const s = $('Book settings').first().json;
const pin = $('Get the pin to book').first().json;
const rows = $input.all().map(i => i.json).filter(r => r.id && String(r.id) !== String(pin.id));
const ms = t => (t ? new Date(t).getTime() : NaN);
const now = Date.now(), WEEK = 7 * 864e5;
const posted = rows.filter(r => r.status === 'posted').map(r => ms(r.posted_at)).filter(x => !isNaN(x));
const taken = rows.filter(r => r.status === 'scheduled').map(r => ms(r.scheduled_for)).filter(x => !isNaN(x)).concat(posted);
const first = posted.length ? Math.min(...posted) : now;
const last = taken.length ? Math.max(...taken) : null;
const week = Math.floor((Math.max(last ?? now, now) - first) / WEEK);
const step = [...s.pace].sort((a, b) => b.from_week - a.from_week).find(p => p.from_week <= week) || { per_week: 3 };
const perWeek = Math.min(Math.max(Number(step.per_week) || 1, 1), s.max_per_week);
const gap = WEEK / perWeek;
let t = last == null ? now + 15 * 6e4 : Math.max(now + 15 * 6e4, last + gap + (Math.random() - 0.5) * 0.3 * gap);
if (s.first_slot_after) t = Math.max(t, ms(s.first_slot_after));
const [fh, fm] = s.post_from.split(':').map(Number), [uh, um] = s.post_until.split(':').map(Number);
let d = DateTime.fromMillis(t).setZone(s.timezone);
const mins = d.hour * 60 + d.minute;
if (mins < fh * 60 + fm || mins > uh * 60 + um) {
  if (mins > uh * 60 + um) d = d.plus({ days: 1 });
  d = d.set({ hour: fh, minute: fm, second: 0, millisecond: 0 }).plus({ minutes: Math.floor(Math.random() * 90) });
}
return [{ json: { slot: d.toUTC().toISO({ suppressMilliseconds: true }), per_week: perWeek, account_week: week } }];

// Zernio's post id, or why it said no.
const z = $input.first().json || {};
const id = z.post?._id || z._id || '';
return [{ json: { id: $('Get the pin to book').first().json.id, post_id: id, status: id ? 'scheduled' : 'failed',
  scheduled_for: id ? $('Pick a slot').first().json.slot : null,
  error: id ? '' : String(z.error?.message || z.error || z.message || JSON.stringify(z)).slice(0, 400) } }];

// published -> posted with the pin link; failed or cancelled -> failed with the reason; anything else waits for the next run.
const rows = $('Slot passed?').all().map(i => i.json);
const out = [];
$input.all().forEach((it, i) => {
  const r = rows[i]; if (!r) return;
  if (it.json.error && /\b404\b/.test(String(it.json.error.message || it.json.error))) {   // deleted in Zernio
    out.push({ json: { id: r.id, status: 'failed', pin_url: '', posted_at: null, error: 'Zernio has no post with this id (deleted there?). Try again books a new slot.' } }); return;
  }
  const post = it.json.post || it.json;
  const t = (post.platforms || []).find(p => p.platform === 'pinterest') || {};
  const status = t.status || post.status || '';
  if (status === 'published' || post.status === 'published')
    out.push({ json: { id: r.id, status: 'posted', pin_url: t.platformPostUrl || (t.platformPostId ? 'https://www.pinterest.com/pin/' + t.platformPostId + '/' : ''), posted_at: r.scheduled_for, error: '' } });
  else if (['failed', 'cancelled'].includes(status) || ['failed', 'cancelled'].includes(post.status))
    out.push({ json: { id: r.id, status: 'failed', pin_url: '', posted_at: null, error: String(t.errorMessage || t.error || post.error || status).slice(0, 400) } });
});
return out;

// One line per pin that changed, for the log channel.
const rows = $('Read the result').all().map(i => i.json);
const pins = Object.fromEntries($('Slot passed?').all().map(i => [String(i.json.id), i.json]));
if (!rows.length) return [];
const text = rows.map(r => r.status === 'posted' ? `:pushpin: <${r.pin_url}|${pins[r.id]?.product_title}> on ${pins[r.id]?.board_name}` : `:x: ${pins[r.id]?.product_title}: ${r.error}`).join('\n');
return [{ json: { channel: $('Sync settings').first().json.log_channel, text: 'Pins published\n' + text } }];
